#!/usr/bin/env bun
// bun scripts/gen-types.ts [--world plugin|plugin-minimal]
//
// Generates TypeScript types for the guest side of the WIT (plugin-api/wit) with `jco types`, into sdk/js/types/, plus two
// small generated files derived from the same WIT. Nothing generated is edited by hand; all of it is git-ignored and
// regenerated whenever the WIT changes (also by scripts/build.ts and plugin-api/samples/test.ts).
//
//   types/interfaces/*.d.ts, types/plugin.d.ts   what `jco types` writes (one module per interface)
//   types/ambient.d.ts                           `declare module "zinc:plugin/<iface>@0.1.0"` for every import, so
//                                                `import ui from "zinc:plugin/ui@0.1.0"` is typed (default import = the interface)
//   types/exports.d.ts                           `Exports`: the shape of every exported interface (what a plugin implements)
//   types/index.d.ts                             pulls the two above in with one reference
//   src/generated/exports.ts                     the list of exported functions with their return types, so
//                                                definePlugin() can fill in defaults for the ones a plugin does not write
import { mkdir, readdir, readFile, rm, writeFile } from "node:fs/promises";
import { join, resolve } from "node:path";

const here = resolve(import.meta.dir, "..");
const wit = resolve(here, "..", "..", "wit");
const out = join(here, "types");
const genSrc = join(here, "src", "generated");

const args = process.argv.slice(2);
const wi = args.indexOf("--world");
const world = wi >= 0 ? args[wi + 1] : "plugin";

await rm(out, { recursive: true, force: true });
await rm(genSrc, { recursive: true, force: true });
await mkdir(out, { recursive: true });
await mkdir(genSrc, { recursive: true });

// jco lives in plugin-host's node_modules (one install for the repo); fall back to bunx.
const localJco = resolve(here, "..", "..", "..", "plugin-host", "node_modules", ".bin", process.platform === "win32" ? "jco.exe" : "jco");
const cmd = (await Bun.file(localJco).exists())
	? [localJco, "types", wit, "--world-name", world, "-o", out, "--quiet"]
	: ["bunx", "@bytecodealliance/jco", "types", wit, "--world-name", world, "-o", out, "--quiet"];
const p = Bun.spawn(cmd, { stdout: "pipe", stderr: "pipe" });
const [stdout, stderr, code] = await Promise.all([new Response(p.stdout).text(), new Response(p.stderr).text(), p.exited]);
if (code !== 0) {
	console.error(stderr || stdout);
	process.exit(code);
}

const entry = `${world}.d.ts`;
const world_d_ts = await readFile(join(out, entry), "utf8");
const camel = (s: string) => s.replace(/-([a-z0-9])/g, (_, c: string) => c.toUpperCase());
const slug = (iface: string) => `zinc-plugin-${iface}`;

// `export type * as ZincPluginUi010 from './interfaces/zinc-plugin-ui.js'; // import zinc:plugin/ui@0.1.0`
const imports = [...world_d_ts.matchAll(/\/\/ import zinc:plugin\/([a-z0-9-]+)@([0-9.]+)/g)].map((m) => ({ iface: m[1], version: m[2] }));
const exportsList = [...world_d_ts.matchAll(/export \* as (\w+) from '\.\/interfaces\/([a-z0-9-]+)\.js'; \/\/ export zinc:plugin\/([a-z0-9-]+)@/g)].map((m) => ({
	name: m[1],
	file: m[2],
	iface: m[3],
}));
if (!imports.length || !exportsList.length) throw new Error("could not read imports/exports from " + entry);

const ambient = imports
	.map(
		({ iface, version }) =>
			`declare module "zinc:plugin/${iface}@${version}" {\n\tconst m: typeof import("./interfaces/${slug(iface)}.js");\n\texport default m;\n}\n`,
	)
	.join("\n");
await writeFile(join(out, "ambient.d.ts"), `// generated by sdk/js/scripts/gen-types.ts; do not edit\n${ambient}`);

const exp = exportsList.map((e) => `\t${e.name}: typeof import("./interfaces/${e.file}.js");`).join("\n");
await writeFile(join(out, "exports.d.ts"), `// generated by sdk/js/scripts/gen-types.ts; do not edit\nexport interface Exports {\n${exp}\n}\n`);
await writeFile(join(out, "index.d.ts"), `// generated by sdk/js/scripts/gen-types.ts; do not edit\n/// <reference path="./ambient.d.ts" />\nexport type { Exports } from "./exports";\n`);

// the exported functions and their return types, from the per-interface .d.ts
const table: { iface: string; fn: string; ret: string; fill?: string; file: string }[] = [];
for (const e of exportsList) {
	const text = await readFile(join(out, "interfaces", `${e.file}.d.ts`), "utf8");
	for (const m of text.matchAll(/^export function (\w+)\(([^)]*)\): (.+);$/gm)) table.push({ iface: e.name, fn: m[1], ret: m[3], file: e.file });
}

// ---- record defaults ----------------------------------------------------------------------------------------------------
// The QuickJS guest traps ("unreachable") when a record it passes to the host lacks a required field. `fill()` in
// src/defaults.ts adds them from this table: for every record (key `<interface>/<Name>`), the required fields with a default
// spec and the optional fields that hold a record (so nested records get filled too).
//   spec: "v:<key>" variant whose cases carry records (see VARIANT_CASES), "s" string, "n" number, "g" bigint, "f" false, "e:<first case>" enum, "a" or "a:<spec>" list, "r:<key>" record,
//         "u8" Uint8Array, "-" no default (variant, tuple: left alone).
type Alias = { kind: "alias"; to: string } | { kind: "prim"; spec: string } | { kind: "enum"; first: string } | { kind: "record"; key: string } | { kind: "variant"; key?: string };
const files = (await readdir(join(out, "interfaces"))).filter((f) => f.endsWith(".d.ts"));
const mods = new Map<string, { text: string; types: Map<string, Alias> }>();
for (const f of files) mods.set(f.replace(/\.d\.ts$/, ""), { text: await readFile(join(out, "interfaces", f), "utf8"), types: new Map() });
const ifaceOf = (mod: string) => mod.replace(/^zinc-plugin-/, "");
const cases = new Map<string, { tag: string; val?: string }>();
const variants = new Map<string, { mod: string; cases: string[] }>();
const fieldsOf = new Map<string, { name: string; opt: boolean; type: string }[]>();
for (const [mod, m] of mods) {
	const text = m.text.replace(/\/\*[\s\S]*?\*\//g, "");
	for (const r of text.matchAll(/^export interface (\w+) \{\n([\s\S]*?)^\}/gm)) {
		const body = r[2];
		const caseM = body.match(/^\s+tag: '([^']+)',?\n(?:\s+val: (.+),?\n)?/m);
		if (caseM) {
			cases.set(`${mod}:${r[1]}`, { tag: caseM[1], val: caseM[2]?.replace(/,$/, "") });
			continue; // a variant case
		}
		const key = `${ifaceOf(mod)}/${r[1]}`;
		const fields = [...body.matchAll(/^\s+(\w+)(\?)?: (.+),$/gm)].map((x) => ({ name: x[1], opt: !!x[2], type: x[3] }));
		fieldsOf.set(key, fields);
		m.types.set(r[1], { kind: "record", key });
	}
	for (const r of text.matchAll(/^export type (\w+) = (.+);$/gm)) {
		const rhs = r[2].trim();
		let a: Alias;
		const imp = rhs.match(/^import\('\.\/([\w-]+)\.js'\)\.(\w+)$/);
		if (imp) a = { kind: "alias", to: `${imp[1]}:${imp[2]}` };
		else if (rhs === "string") a = { kind: "prim", spec: "s" };
		else if (rhs === "number") a = { kind: "prim", spec: "n" };
		else if (rhs === "bigint") a = { kind: "prim", spec: "g" };
		else if (rhs === "boolean") a = { kind: "prim", spec: "f" };
		else if (/^"[^"]*"( \| "[^"]*")*$/.test(rhs)) a = { kind: "enum", first: rhs.match(/^"([^"]*)"/)![1] };
		else if (/^[A-Z]\w*( \| [A-Z]\w*)+$/.test(rhs) && rhs.split(" | ").every((c) => cases.has(`${mod}:${c}`))) {
			variants.set(`${ifaceOf(mod)}/${r[1]}`, { mod, cases: rhs.split(" | ") });
			a = { kind: "variant", key: `${ifaceOf(mod)}/${r[1]}` };
		} else a = { kind: "variant" };
		m.types.set(r[1], a);
	}
}
function specOf(mod: string, type: string, depth = 0): string {
	type = type.trim();
	if (type.endsWith(" | undefined")) return specOf(mod, type.slice(0, -12), depth);
	if (type === "string") return "s";
	if (type === "number") return "n";
	if (type === "bigint") return "g";
	if (type === "boolean") return "f";
	if (type === "Uint8Array") return "u8";
	if (/^(Uint|Int)(16|32)Array$|^(BigInt|BigUint)64Array$|^Float(32|64)Array$/.test(type)) return "a";
	const arr = type.match(/^Array<(.+)>$/);
	if (arr) {
		const inner = specOf(mod, arr[1], depth);
		return /[rv]:/.test(inner) ? `a:${inner}` : "a";
	}
	if (/^[A-Z]\w*$/.test(type) && depth < 12) {
		const t = mods.get(mod)?.types.get(type);
		if (!t) return "-";
		if (t.kind === "alias") {
			const [m2, n2] = t.to.split(":");
			return specOf2(m2, n2, depth + 1);
		}
		return specOfAlias(mod, t);
	}
	return "-";
}
function specOf2(mod: string, name: string, depth: number): string {
	const t = mods.get(mod)?.types.get(name);
	if (!t) return "-";
	if (t.kind === "alias") {
		const [m2, n2] = t.to.split(":");
		return depth < 12 ? specOf2(m2, n2, depth + 1) : "-";
	}
	return specOfAlias(mod, t);
}
const specOfAlias = (_mod: string, t: Alias): string => (t.kind === "prim" ? t.spec : t.kind === "enum" ? `e:${t.first}` : t.kind === "record" ? `r:${t.key}` : t.kind === "variant" && t.key ? `v:${t.key}` : "-");
const defaults: Record<string, { req: Record<string, string>; opt: Record<string, string> }> = {};
for (const [key, fields] of fieldsOf) {
	const mod = `zinc-plugin-${key.split("/")[0]}`;
	const req: Record<string, string> = {};
	const opt: Record<string, string> = {};
	for (const f of fields) {
		const spec = specOf(mod, f.type);
		if (f.opt) {
			if (/[rv]:/.test(spec)) opt[f.name] = spec;
		} else req[f.name] = spec;
	}
	defaults[key] = { req, opt };
}
// variants whose cases carry records (or lists of them): `{ tag, val }` values get `val` filled by the case's spec
const variantTable: Record<string, Record<string, string>> = {};
for (const [key, v] of variants) {
	const caseSpecs: Record<string, string> = {};
	for (const c of v.cases) {
		const cs = cases.get(`${v.mod}:${c}`)!;
		if (!cs.val) continue;
		const spec = specOf(v.mod, cs.val);
		if (/[rv]:/.test(spec)) caseSpecs[cs.tag] = spec;
	}
	if (Object.keys(caseSpecs).length) variantTable[key] = caseSpecs;
}
await writeFile(
	join(genSrc, "defaults.ts"),
	`// generated by sdk/js/scripts/gen-types.ts from plugin-api/wit; do not edit\nexport const RECORD_DEFAULTS: Record<string, { req: Record<string, string>; opt: Record<string, string> }> = ${JSON.stringify(defaults)};\nexport const VARIANT_CASES: Record<string, Record<string, string>> = ${JSON.stringify(variantTable)};\n`,
);
// the exported functions: what each returns, and the fill spec of the result so definePlugin() can complete returned records
const returns = table.map(({ file, ...t }) => {
	const spec = specOf(file, t.ret.replace(/^Promise<(.+)>$/, "$1"));
	return /[rv]:/.test(spec) ? { ...t, fill: spec } : t;
});
await writeFile(
	join(genSrc, "exports.ts"),
	`// generated by sdk/js/scripts/gen-types.ts from plugin-api/wit; do not edit
export const EXPORT_FUNCTIONS: readonly { iface: string; fn: string; ret: string; fill?: string }[] = ${JSON.stringify(returns, null, "	")};
`,
);
console.log(`generated types for world ${world}: ${imports.length} imports, ${exportsList.length} exports, ${table.length} export functions (${out})`);
